mapper.select:
SELECT * FROM vs_drama_video WHERE delete_time IS NULL AND site_id = #{siteId}
AND status = #{status}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR performer LIKE CONCAT('%', #{keyword}, '%') OR tags LIKE CONCAT('%', #{keyword}, '%'))
AND FIND_IN_SET(#{categoryId}, category_ids)
ORDER BY is_recommend DESC, weigh DESC, id DESC
